using System.Text.Json.Nodes;

namespace MiniRP.Core;

internal sealed class PluginAgent(string name, AgentSession session, PageSource web)
{
    private const string LocalizationGuidance = """
        Localize the plugin's human-readable text. Write meaningful source strings in the manifest and declare `i18n.defaultLocale` and `i18n.locales`.
        Use BCP 47 language tags and map JSON Pointers, such as `/skills/0/title`, to translated strings. Include the languages the user requests.
        Cover plugin names and descriptions, skill and tool display titles and descriptions, setting and option labels, attachment labels, card titles, and card labels.
        Keep identifiers, option values, handler bindings, Action and Asset URLs, tool names, permissions, and schema field names stable across languages.

        Declare static card copy in `cards[].labels` and translate its strings with `/cards/{index}/labels/{key}` pointers. Keep the OpenUI program fixed and read the translated values through `$labels`.
        For notifications, errors and cards generated by JavaScript, bundle the plugin SDK and use `defineI18n` with `getLocale(api)`. Provide source messages as the fallback and preserve interpolation placeholders.
        For bundled plugins, match the application's supported languages for every card title and label. Check a translated language, an RTL language when supported, and the fallback. When a saved card changes language, confirm its data and current interaction state are retained.
        """;

    internal static string LanguageGuidance(string locale) =>
        "Report language: Use the user-facing language specified in the delegation for progress updates and the final report. " +
        $"Otherwise use the application language ({locale}). Keep code identifiers, API fields and quoted source text unchanged.";

    private const string ToolPresentationGuidance = """
        For plugin tools with structured arguments or results people need to inspect, declare a read-only OpenUI tool trace presentation for each relevant phase.
        Read `plugin-docs` with `topic:"api", query:"工具轨迹展示"`. Reference static signed manifest cards in `skills[].tools[].presentation`.
        Bind `$data`, `$tool` and `$phase` through a fixed program with read-only components. Use `$title` and `$labels` for the localized card copy and `$locale` for the display language.
        Verify a real chat call with a populated card and raw JSON copy. Verify the raw trace fallback with a tool error or unavailable card.
        Report both observed outcomes, or hand off the exact fixture and expected results for platforms you cannot exercise.
        """;

    public Task<JsonObject> Run(string instruction, CancellationToken ct)
    {
        Task<JsonObject> Ask() => session.Run(
            $"""
            You are PluginAgent working on {name}. Complete the delegated implementation and tests. Batch activation for the skills you need next. Their tools are available from the next model request.

            Read plugin-docs before using an unfamiliar MiniRP API, manifest field, or tool. Use `development` for the workflow or `多文件 JavaScript`, `assets` with `## Assets` for package resources, and `automation` with `声明状态和卡片` for cards. Batch independent lookups. Use search and open_url, or curl for a third-party API or external download when the task needs it.

            {LocalizationGuidance}

            {ToolPresentationGuidance}

            Ensemble ChatAgents and their optional SearchAgents initialize concurrently. Each character keeps listening to their joined scenes for the life of the Room, including while the user views another scene. Scope work by Room, Chat and participant IDs. For shared state needed during preparation or dialogue, declare Room defaults or initialize idempotently on first use. Reserve room.loaded for work that follows the opening. Verify concurrent calls and different session start orders, including a shared scene with overlapping memberships.

            Activate plugin-dev to manage the draft, starting with plugin_file_list. Activate assets to read and edit the listed URLs or create new files. Link new package paths with plugin_file_add. Preserve the assigned manifest identity. Test a multi-file plugin through a `.mjs` entry and a handler that uses an imported module. Keep any container files in a project-specific directory under the preset's shared /workspace.

            Declare the smallest necessary permissions and scope. Validate Action inputs and guard repeated side effects. Run a small draft Action with a known input and check the output. For Android cards, run the card preview and inspect diagnostics and rendered text. After a failure, identify the field, path, scope or output that failed. Check the contract or current file, change one relevant thing, and rerun the fixture. Reuse successful evidence while its inputs and source are unchanged.

            Publish or remove only as authorized. For publication, use the verified draft input and serialize the successful Action's inner `result` into `expected_result_json`. Check the installed generation's verification and scope. Then exercise the real entry point. Read your installed public `minirp://assets/` URL with the assets skill. When an entry point needs another role or user interaction, hand off the exact action, input and expected result to PresetAgent. Report the observed results and any checks that remain.
            """,
            instruction, AgentSkill.SubagentTask, ct);
        return session.Assets?.PresetResearch is { } research ? research.Run(session, web, Ask) : Ask();
    }
}
